use axum::{routing::{get,post,put},Router,http::{HeaderValue,header}};

use crate::{AppState,auth,features::{people,organization,terms,volunteers,hiring,lists,dashboard,configuration,lifecycle,notifications,detail,requests,push,alert_preferences,request_follow_up,schedules}};
pub fn router(s:AppState)->Router {
 let mut api=Router::new()
 .route("/auth/me",get(auth::me)).route("/auth/logout",post(auth::logout))
 .route("/dashboard",get(dashboard::dashboard))
 .route("/requests",get(requests::list).post(requests::create)).route("/requests/recipients",get(requests::recipients)).route("/requests/{id}",get(requests::get)).route("/requests/{id}/respond",post(requests::respond))
 .route("/push/config",get(push::config)).route("/push/subscriptions",post(push::subscribe).delete(push::unsubscribe))
 .route("/push/subscriptions/status",post(push::subscription_status))
 .route("/notification-preferences",get(alert_preferences::get).put(alert_preferences::put))
 .route("/requests/{id}/follow-up",get(request_follow_up::details).put(request_follow_up::schedule))
 .route("/requests/{id}/remind",post(request_follow_up::remind_now))
 .route("/notifications",get(notifications::list)).route("/notifications/{id}/read",post(notifications::read))
 .route("/users",get(people::list).post(lifecycle::pending_person)).route("/users/{id}",get(people::get).patch(people::update))
 .route("/users/{id}/directs",get(people::directs)).route("/users/{id}/service-years",get(people::years))
 .route("/users/{id}/service-years/{year}",put(people::set_year).delete(people::delete_year))
 .route("/users/{id}/skills/{skill}",put(people::set_skill).delete(people::remove_skill))
 .route("/skills",get(people::skills).post(people::create_skill))
 .route("/organization/tree",get(organization::tree)).route("/departments",get(detail::departments).post(organization::create_department)).route("/divisions",get(detail::divisions).post(organization::create_division))
 .route("/events",get(organization::events).post(organization::create_event)).route("/events/{id}",axum::routing::patch(organization::update_event))
 .route("/schedules",get(schedules::list).post(schedules::create)).route("/schedules/{id}/claim",post(schedules::claim))
 .route("/departments/{id}",get(detail::department).patch(lifecycle::department)).route("/divisions/{id}",axum::routing::patch(lifecycle::division))
 .route("/departments/{id}/members",get(lifecycle::members)).route("/departments/{id}/members/{user}",axum::routing::patch(lifecycle::member_activity))
 .route("/profile-fields",get(organization::fields).post(organization::create_field))
 .route("/people-page-fields",get(organization::people_page_fields))
 .route("/users/{id}/profile-fields",get(configuration::profile).patch(configuration::update_profile)).route("/users/{id}/export",get(detail::export_person))
 .route("/permission-grants",get(configuration::grants).post(configuration::grant)).route("/permission-grants/{id}",axum::routing::delete(configuration::revoke))
 .route("/levels",get(detail::levels).post(configuration::create_level)).route("/position-levels/{id}",axum::routing::patch(configuration::map_level))
 .route("/form-templates",get(configuration::templates).post(configuration::create_template)).route("/form-templates/{id}/versions",post(configuration::template_version))
 .route("/terms/applicable",get(terms::applicable)).route("/terms/compliance",get(terms::compliance))
 .route("/terms",get(terms::list).post(terms::create)).route("/terms/{id}/versions",post(terms::version)).route("/terms/{id}/publish",post(terms::publish)).route("/term-versions/{id}/sign",post(terms::sign))
 .route("/volunteer/entries",get(volunteers::list).post(volunteers::create))
 .route("/volunteer/entries/{id}",get(detail::entry).patch(lifecycle::edit_entry)).route("/volunteer/entries/{id}/reopen",post(lifecycle::reopen))
 .route("/volunteer/entries/{id}/submit",post(volunteers::submit)).route("/volunteer/entries/{id}/withdraw",post(volunteers::withdraw)).route("/volunteer/entries/{id}/approval-qr",post(volunteers::qr))
 .route("/volunteer/approval-preview",get(volunteers::preview)).route("/volunteer/approval-decisions",post(volunteers::decide)).route("/volunteer/manual-decisions",post(volunteers::decide_manual)).route("/volunteer/reports/hours",get(volunteers::report))
 .route("/positions",get(hiring::positions).post(hiring::create_position)).route("/positions/{id}",get(detail::position).patch(hiring::update_position))
 .route("/positions/{id}/owner",post(lifecycle::owner))
 .route("/default-questions",get(hiring::questions).post(hiring::create_question))
 .route("/applications",get(hiring::applications).post(hiring::apply)).route("/applications/{id}",get(hiring::application).patch(hiring::edit_application)).route("/applications/{id}/submit",post(hiring::submit_application)).route("/applications/{id}/finalize",post(hiring::finalize))
 .route("/interviews",get(hiring::interviews).post(hiring::schedule)).route("/interviews/{id}/my-decision",put(hiring::recommend)).route("/interviews/{id}/notes",get(hiring::notes).post(hiring::add_note))
 .route("/interviews/{id}",get(detail::interview).patch(lifecycle::interview)).route("/interviews/{id}/interviewers",post(lifecycle::add_interviewer))
 .route("/saved-lists",get(lists::list).post(lists::create)).route("/saved-lists/{id}",get(detail::saved_list).delete(lists::delete).patch(lifecycle::update_list)).route("/saved-lists/{id}/run",post(lists::run))
 .route("/bulk-changes/{id}",get(lifecycle::job))
 .route("/bulk-changes/preview",post(lists::preview)).route("/bulk-changes/execute",post(lists::execute)).route("/bulk-changes",get(lists::jobs))
 .route("/audit-events",get(dashboard::audit));
 if s.config.dev_auth {api=api.route("/auth/dev/bootstrap",post(auth::bootstrap)).route("/auth/dev/switch",post(auth::switch));}
 let legacy_auth=Router::new().route("/me",get(auth::me)).route("/dev/bootstrap",post(auth::bootstrap)).route("/dev/switch",post(auth::switch));
 Router::new().nest("/api/v1",api).nest("/api/auth",legacy_auth)
 .route("/health/live",get(crate::openapi::live))
 .route("/health/ready",get(crate::openapi::ready)).route("/api-docs/openapi.json",get(crate::openapi::document))
 .layer(axum::middleware::from_fn_with_state(s.clone(),auth::csrf))
 .layer(axum::extract::DefaultBodyLimit::max(128*1024))
 .layer(tower_http::set_header::SetResponseHeaderLayer::overriding(header::CACHE_CONTROL,HeaderValue::from_static("no-store")))
 .layer(tower_http::set_header::SetResponseHeaderLayer::overriding(header::X_CONTENT_TYPE_OPTIONS,HeaderValue::from_static("nosniff")))
 .layer(tower_http::trace::TraceLayer::new_for_http().make_span_with(|request:&axum::http::Request<_>|tracing::info_span!("http",method=%request.method(),path=%request.uri().path())))
 .with_state(s)
}
